<section class="page-intro"><span class="eyebrow">A LITTLE LOVE</span><h1>Words from our community</h1><p>Your stories make the charm.</p></section><section class="section reviews-layout"><div><div class="review-grid"><?php $reviews=rows("SELECT r.*,p.name AS product_name FROM reviews r LEFT JOIN products p ON p.id=r.product_id WHERE r.status='approved' ORDER BY r.created_at DESC");foreach($reviews as $r): ?><blockquote><div class="stars" aria-label="<?= (int)$r['rating'] ?> out of 5 stars"><?= str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating']) ?></div><p>“<?= e($r['comment']) ?>”</p><cite><?= e($r['name']) ?></cite><?php if($r['product_name']): ?><small><?= e($r['product_name']) ?></small><?php endif ?></blockquote><?php endforeach ?></div><?php if(!$reviews): ?><div class="empty-state"><h2>Every story starts somewhere.</h2><p>Be the first to share your M’s Charm experience.</p></div><?php endif ?></div><form class="panel" method="post" action="/reviews"><?= csrf_field() ?><h2>Share a little love</h2><p>Reviews appear after approval by our team.</p><?php if(!current_user()): ?><label>Your name<input name="name" required maxlength="120"></label><?php endif ?><label>Your piece (optional)<select name="product_id"><option value="">My store experience</option><?php foreach(products() as $p): ?><option value="<?= e($p['id']) ?>" <?= ($_GET['product']??'')===$p['id']?'selected':'' ?>><?= e($p['name']) ?></option><?php endforeach ?></select></label><label>Your rating<select name="rating" required><option value="5">★★★★★ — Loved it</option><option value="4">★★★★☆ — Very good</option><option value="3">★★★☆☆ — Good</option><option value="2">★★☆☆☆ — Could be better</option><option value="1">★☆☆☆☆ — Disappointed</option></select></label><label>Your review<textarea name="comment" required maxlength="2000" rows="5"></textarea></label><button class="button full">Submit review</button></form></section>
